_UNPACKED_INDIC_CACHE: Dict[str, Tuple[Set[str], Set[str]]] = {}


def _unpack_indic_word_list(packed: str, alpha: str) -> Set[str]:
    if not packed:
        return set()
    idx_map = _INDIC_LEX_SAFE_IDX
    words: Set[str] = set()
    prev = ""
    for entry in packed.split("|"):
        if not entry:
            continue
        lcp = idx_map[entry[0]]
        tail = "".join(alpha[idx_map[c]] for c in entry[1:])
        word = prev[:lcp] + tail
        words.add(word)
        prev = word
    return words


def get_indic_lexicon(lang: str) -> Tuple[Set[str], Set[str]]:
    """Return (core_words, ext_words) sets for an Indic language code, lazily unpacked."""
    cached = _UNPACKED_INDIC_CACHE.get(lang)
    if cached is not None:
        return cached
    raw = _PACKED_INDIC_LEXICONS.get(lang)
    if raw is None:
        empty: Tuple[Set[str], Set[str]] = (set(), set())
        _UNPACKED_INDIC_CACHE[lang] = empty
        return empty
    alpha, p_core, p_ext = raw
    pair = (_unpack_indic_word_list(p_core, alpha), _unpack_indic_word_list(p_ext, alpha))
    _UNPACKED_INDIC_CACHE[lang] = pair
    return pair


def detect_indic_vocab_lang(vocab_list: list) -> str:
    """Identify Indic language code directly from SentencePiece vocabulary script & markers."""
    probe = "".join(vocab_list[2:60])
    for ch in probe:
        cp = ord(ch)
        if 0x0980 <= cp <= 0x09FF: return "bn"
        if 0x0A00 <= cp <= 0x0A7F: return "pa"
        if 0x0A80 <= cp <= 0x0AFF: return "gu"
        if 0x0B00 <= cp <= 0x0B7F: return "or"
        if 0x0B80 <= cp <= 0x0BFF: return "ta"
        if 0x0C00 <= cp <= 0x0C7F: return "te"
        if 0x0C80 <= cp <= 0x0CFF: return "kn"
        if 0x0D00 <= cp <= 0x0D7F: return "ml"
    vset = set(vocab_list)
    if "\u0933" in probe or "\u2581\u0906\u0939\u0947" in vset or "\u2581\u0928\u093e\u0939\u0940" in vset or "\u2581\u0915\u093e\u0939\u0940" in vset:
        return "mr"
    if "\u2581\u0939\u0948" in vset or "\u2581\u092e\u0947\u0902" in vset or "\u2581\u0915\u0947" in vset or "\u2581\u0915\u094b" in vset:
        return "hi"
    if any(0x0900 <= ord(c) <= 0x097F for c in probe):
        return "sa"
    return "en"


def classify_indic_word(word: str, lang: str, core_set: Set[str], ext_set: Set[str]) -> int:
    """Classify an Indic word into lexical scoring tiers (3=core, 2=ext, 4=compound, 1=short, -1=bad halant, 0=oov)."""
    if len(word) < 2:
        return 0
    if word in core_set:
        return 3
    if word in ext_set:
        return 2 if len(word) >= 3 else 1
    if word[-1] in _INDIC_BRAHMIC_VIRAMAS and len(word) >= 3:
        bare = word[:-1]
        if lang == "or" or bare in core_set or bare in ext_set:
            return -1
    if lang == "te" and len(word) >= 4 and word.endswith("\u0c1f\u0c02"):
        dam_form = word[:-2] + "\u0c21\u0c02"
        if dam_form in core_set or dam_form in ext_set:
            return 2
    if lang == "bn" and len(word) >= 5 and word.endswith("\u09bf\u09a8\u09c7"):
        vstem = word[:-3]
        if (vstem + "\u09be") in core_set or (vstem + "\u09be") in ext_set or (vstem + "\u09c7") in ext_set:
            return 2
    if lang == "ml" and "\u0d7c\u0d23" in word:
        alt = word.replace("\u0d7c\u0d23\u0d4d\u0d23", "\u0d7c\u0d23")
        alt2 = alt.replace("\u0d7c\u0d23", "\u0d7c\u0d23\u0d4d\u0d23")
        if alt in ext_set or alt2 in ext_set:
            return 2
    for suf in _INDIC_PRODUCTIVE_SUFFIXES.get(lang, ()):
        if word.endswith(suf) and len(word) - len(suf) >= 2:
            stem = word[: -len(suf)]
            if stem in core_set or stem in ext_set:
                return 2
            if lang == "ml" and stem.endswith("\u0d3e") and len(stem) >= 3:
                short_stem = stem[:-1]
                if short_stem in core_set or short_stem in ext_set:
                    return 2
    if len(word) >= 6:
        for split_idx in range(3, len(word) - 2):
            s1 = word[:split_idx]
            s2 = word[split_idx:]
            if (s1 in core_set or s1 in ext_set) and (s2 in core_set or s2 in ext_set):
                return 4
    return 0


def score_indic_word(word: str, lang: str, core_set: Set[str], ext_set: Set[str]) -> float:
    tier = classify_indic_word(word, lang, core_set, ext_set)
    if tier == 3:
        return 2.05
    if tier == 4:
        return 1.75
    if tier == 2:
        if len(word) <= 3:
            return 1.25
        if len(word) <= 5:
            return 1.55
        return 1.80
    if tier == -1:
        return -1.75
    return 0.0
